<?php
namespace Tests\Feature\Admin;
use App\Models\{Brand,Category,Product,ProductImage,ProductVariant,User};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
use Tests\TestCase;
class ProductManagementTest extends TestCase {
 use RefreshDatabase;
 private User $admin; private Category $category; private Brand $brand; private Product $product;
 protected function setUp(): void { parent::setUp(); $this->admin=User::factory()->create(['role'=>'admin']); $this->category=Category::create(['name'=>'Điện thoại','slug'=>'dien-thoai','is_active'=>true]); $this->brand=Brand::create(['name'=>'PhoneBrand','slug'=>'phonebrand','is_active'=>true]); $this->product=Product::create(['category_id'=>$this->category->id,'brand_id'=>$this->brand->id,'name'=>'Phone A','slug'=>'phone-a','is_active'=>true]); }
 private function admin(){return $this->actingAs($this->admin);}
 private function data(array $over=[]): array {return array_merge(['name'=>'Phone B','slug'=>'phone-b','category_id'=>$this->category->id,'brand_id'=>$this->brand->id,'description'=>'Mô tả','specifications'=>'RAM: 8GB','is_active'=>1],$over);}
 public function test_access_is_restricted(): void { $this->get(route('admin.products.index'))->assertRedirect(route('login')); $this->actingAs(User::factory()->create())->get(route('admin.products.index'))->assertForbidden(); $this->actingAs(User::factory()->create())->post(route('admin.products.store'),$this->data())->assertForbidden(); }
 public function test_admin_can_crud_and_toggle_product(): void { $this->admin()->get(route('admin.products.index'))->assertOk()->assertSee('Phone A'); $this->admin()->post(route('admin.products.store'),$this->data())->assertRedirect(); $p=Product::whereSlug('phone-b')->firstOrFail(); $this->admin()->put(route('admin.products.update',$p),$this->data(['name'=>'Phone C']))->assertRedirect(); $this->assertDatabaseHas('products',['id'=>$p->id,'name'=>'Phone C']); $this->admin()->patch(route('admin.products.status',$p))->assertRedirect(); $this->assertDatabaseHas('products',['id'=>$p->id,'is_active'=>false]); }
 public function test_duplicate_slug_and_variant_validation(): void { Product::create($this->data(['name'=>'Other'])); $this->admin()->post(route('admin.products.store'),$this->data())->assertSessionHasErrors('slug'); $v=ProductVariant::create(['product_id'=>$this->product->id,'sku'=>'SKU-1','price'=>100,'stock_quantity'=>1]); ProductVariant::create(['product_id'=>$this->product->id,'sku'=>'SKU-2','price'=>100,'stock_quantity'=>1]); $base=['color'=>'Đen','ram'=>'8GB','storage'=>'128GB','stock_quantity'=>1]; $url=route('admin.variants.update',[$this->product,$v]); $this->admin()->put($url,$base+['sku'=>'SKU-2','price'=>100])->assertSessionHasErrors('sku'); $this->admin()->put($url,$base+['sku'=>'SKU-3','price'=>-1])->assertSessionHasErrors('price'); $this->admin()->put($url,$base+['sku'=>'SKU-3','price'=>100,'sale_price'=>101])->assertSessionHasErrors('sale_price'); }
 public function test_variant_cannot_cross_products(): void { $v=ProductVariant::create(['product_id'=>$this->product->id,'sku'=>'SKU-1','price'=>100,'stock_quantity'=>1]); $other=Product::create($this->data(['name'=>'Other','slug'=>'other'])); $this->admin()->post(route('admin.products.variants.store',$this->product),['sku'=>'SKU-NEW','price'=>200,'stock_quantity'=>5])->assertRedirect(); $this->assertDatabaseHas('product_variants',['sku'=>'SKU-NEW','product_id'=>$this->product->id]); $this->admin()->put(route('admin.variants.update',[$other,$v]),['sku'=>'CHANGED','price'=>200,'stock_quantity'=>2])->assertNotFound(); $this->assertDatabaseHas('product_variants',['id'=>$v->id,'sku'=>'SKU-1']); }
 public function test_admin_can_create_and_edit_category_and_brand(): void { $this->admin()->post(route('admin.taxonomy.store','categories'),['name'=>'Tablet','slug'=>'tablet','is_active'=>1])->assertRedirect(); $c=Category::whereSlug('tablet')->firstOrFail(); $this->admin()->put(route('admin.taxonomy.update',['categories',$c->id]),['name'=>'Tablet Pro','slug'=>'tablet-pro','is_active'=>1])->assertRedirect(); $this->assertDatabaseHas('categories',['id'=>$c->id,'name'=>'Tablet Pro']); $this->admin()->post(route('admin.taxonomy.store','brands'),['name'=>'Brand Two','slug'=>'brand-two','is_active'=>1])->assertRedirect(); $b=Brand::whereSlug('brand-two')->firstOrFail(); $this->admin()->put(route('admin.taxonomy.update',['brands',$b->id]),['name'=>'Brand Updated','slug'=>'brand-updated','is_active'=>1])->assertRedirect(); $this->assertDatabaseHas('brands',['id'=>$b->id,'name'=>'Brand Updated']); }
 public function test_images_are_scoped_and_validated(): void { Storage::fake('public'); $other=Product::create($this->data(['name'=>'Other','slug'=>'other'])); $this->admin()->post(route('admin.products.images.store',$this->product),['images'=>[UploadedFile::fake()->image('one.jpg'),UploadedFile::fake()->image('two.png')]])->assertRedirect(); $images=$this->product->images()->get(); $this->assertCount(2,$images); $this->assertTrue($images->first()->is_primary); $this->admin()->patch(route('admin.images.primary',[$this->product,$images->last()]))->assertRedirect(); $this->assertTrue($images->last()->fresh()->is_primary); $foreign=ProductImage::create(['product_id'=>$other->id,'image_path'=>'products/foreign.jpg']); $this->admin()->delete(route('admin.images.destroy',[$this->product,$foreign]))->assertNotFound(); $this->admin()->delete(route('admin.images.destroy',[$this->product,$images->first()]))->assertRedirect(); $this->assertDatabaseMissing('product_images',['id'=>$images->first()->id]); $this->admin()->post(route('admin.products.images.store',$this->product),['images'=>[UploadedFile::fake()->create('script.php',100,'application/php')]])->assertSessionHasErrors('images.0'); }
 public function test_images_can_be_reordered_and_invalid_order_is_rejected(): void { Storage::fake('public'); $this->admin()->post(route('admin.products.images.store',$this->product),['images'=>[UploadedFile::fake()->image('one.jpg'),UploadedFile::fake()->image('two.jpg'),UploadedFile::fake()->image('three.jpg')]]); $ids=$this->product->images()->pluck('id')->all(); $this->admin()->patch(route('admin.images.sort',$this->product),['image_ids'=>array_reverse($ids)])->assertRedirect(); $this->assertSame(array_reverse($ids),$this->product->images()->orderBy('sort_order')->pluck('id')->all()); $this->admin()->patch(route('admin.images.sort',$this->product),['image_ids'=>[$ids[0],$ids[0]]])->assertSessionHasErrors('image_ids.1'); }
 public function test_image_upload_can_target_variant_but_not_another_product(): void { Storage::fake('public'); $variant=ProductVariant::create(['product_id'=>$this->product->id,'sku'=>'TARGET-1','color'=>'Đen','price'=>100,'stock_quantity'=>1]); $other=Product::create($this->data(['name'=>'Other','slug'=>'other-target'])); $foreignVariant=ProductVariant::create(['product_id'=>$other->id,'sku'=>'FOREIGN-1','price'=>100,'stock_quantity'=>1]); $this->admin()->post(route('admin.products.images.store',$this->product),['product_variant_id'=>$variant->id,'images'=>[UploadedFile::fake()->image('variant.jpg')]])->assertRedirect(); $this->assertDatabaseHas('product_images',['product_variant_id'=>$variant->id]); $this->admin()->post(route('admin.products.images.store',$this->product),['product_variant_id'=>$foreignVariant->id,'images'=>[UploadedFile::fake()->image('foreign.jpg')]])->assertStatus(422); }

 public function test_non_admin_cannot_manage_images(): void { Storage::fake('public'); $user=User::factory()->create(); $this->actingAs($user)->post(route('admin.products.images.store',$this->product),['images'=>[UploadedFile::fake()->image('one.jpg')]])->assertForbidden(); }
}